var NUMBER_WORDS = [
    {matcher:/\b(one|a)\b/i,
     value:1},
    {matcher:/(two|\ba\s*(couple|pair)\b)/i,
     value:2},
    {matcher:/(\b(one|a)\b\s*)?half(\s+(a|an))?\b/i,
     value:0.5},
    {matcher:/\bthree\b/i,value:3},
];


var LESS_THAN_TWENTY = [
    'zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten',
    'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'
];

var TENTHS_LESS_THAN_HUNDRED = [
    'zero', 'ten', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'
];

for (let i=0; i<20; i++) {
    let word = LESS_THAN_TWENTY[i];
    NUMBER_WORDS.push({
        matcher : new RegExp('\\b'+word+'\\b','i'),
        value : i
    });
}
for (let t=2; t<10; t++) {
    let tens = TENTHS_LESS_THAN_HUNDRED[t];
    NUMBER_WORDS.push({
        matcher : new RegExp('\\b'+tens+'\\b','i'),
        value : t*10
    });
    for (let i=1; i<10; i++) {
        let ones = LESS_THAN_TWENTY[i];
        NUMBER_WORDS.push({
            matcher : new RegExp('\\b'+tens+'(\\s*|-|–)'+ones+'\\b','i'),
            value : t*10 + i
        });
    }
}

for (let word of NUMBER_WORDS) {
    if (isNaN(word.value)) {
        throw Error(`bad word ${word.matcher} ${word.value}`);
    }
}
NUMBER_WORDS.reverse(); // longest to shortest - match greedy first


function getValueFromNumberWord (s) {
    for (let numberWord of NUMBER_WORDS) {
        // We assume NUMBER_WORDS is in order from most to least
        // specific, so if, for example twenty-two matches twenty and
        // two and twenty-two, twenty-two will come first.
        // I *think* but haven't rigorously confirmed that this works
        // for all numbers with larger numbers being more specific than
        // smaller numbers in terms of regexp matching
        if (s.match(numberWord.matcher)) {
            return numberWord.value
        }
    }
}


var NUMBER_FRACTIONS = [
    {numerator:1,
     denominator:2,
     word:'\u00BD'},
    {numerator:1,
     denominator:4,
     word:'\u00BC'},
    {numerator:3,
     denominator:4,
     word:'\u00BE'},
    {numerator:1,
     denominator:3,
     word:'\u2153'},
    {numerator:2,
     denominator:3,
     word:'\u2154'},
    {numerator:1,
     denominator:5,
     word:'\u2155'},
    {numerator:2,
     denominator:5,
     word:'\u2156'},
    {numerator:3,
     denominator:5,
     word:'\u2157'},
    {numerator:4,
     denominator:5,
     word:'\u2158'},
    {numerator:1,
     denominator:6,
     word:'\u2159'},
    {numerator:5,
     denominator:6,
     word:'\u215A'},
    {numerator:1,
     denominator:8,
     word:'\u215B'},
    {numerator:3,
     denominator:8,
     word:'\u215C'},
    {numerator:5,
     denominator:8,
     word:'\u215D'},
    {numerator:7,
     denominator:8,
     word:'\u215E'},
];

// translation to javascript
/*We assume fractions look like this (I )?N/D */
function fracToFloat (s) {
    if (!s.split) {
        return Number(s); // if we are not a string, just use Number...
    }
    if (['/','⁄'].indexOf(s[s.length-1])>-1) {
        // if we end with a slash, we are not a number...
        return NaN
    }
    var parts = s.split(/\s+/);
    if (parts.length==2) {
	var num = Number(parts[0]);
	var frac = parts[1];
    }
    else {
	var num = 0;
	var frac = parts[0];
    }
    var frac_split = frac.split(/[\/⁄]/);
    if (frac_split.length==2) {
	return  num + (Number(frac_split[0])/Number(frac_split[1]))
    }
    else {
	// let's look for fraction unicode...
	for (var f of NUMBER_FRACTIONS) {
	    if (frac==f.word) {return num+(f.numerator/f.denominator)}
	}
    }
    // If we are still here, let's just try a regular conversion
    if (s.match(/[0-9]([,][0-9][0-9][0-9])+([.][0-9]+)?$/)) {
        s = s.replace(/[,]/g,'');
    }
    if (s.match(/[0-9]([.][0-9][0-9][0-9])+([,][0-9]+)?$/)) {
        s = s.replace(/[.]/g,'');
    }
    let val = Number(s);
    if (!isNaN(val)) {
        return val
    }
    else {
        let wordValue = getValueFromNumberWord(s);
        if (wordValue) {
            return wordValue
        }
    }
}


var numBase = `([0-9]|${NUMBER_FRACTIONS.map((f)=>f.word).join('|')}`;
numBase += '|' + NUMBER_WORDS.map((w)=>w.matcher.toString().replace(/(^\/|\/i$)/g,'')).join('|');
var numNaked = numBase + ')';
var numMid = numBase + '|[,./⁄])'; 
var numMatchString = `${numNaked}+(${numMid}*${numNaked}+)?`;
var fracMatchString = `(${NUMBER_FRACTIONS.map((f)=>f.word).join('|')}|\\d[/⁄]\\d)`;
numMatchString = `${numMatchString}(\\s+${fracMatchString})?`;
countGroupsInRegexp(numMatchString);

var timeUnits = undefined;
var timeConversions = {}; // gets populated in getTimeUnits()
var timeEquivs = {
    'seconds':['s','sec','secs','second'],
    'minutes':['min','minute','mins','min.'],
    'hours':['hr','hr.','hour','hrs'],
    'days':['day'],
    'weeks':['week','wk'],
};

var timeEquivRegexps = {
};

for (var unit in timeEquivs) {
    timeEquivs[unit].push(unit);
    timeEquivRegexps[unit] = new RegExp(`(${numMatchString})\\s+(${timeEquivs[unit].join('|')})`);
}

function getTimeUnits () { /* singleton */
    if (timeUnits) {return timeUnits}
    else {
        timeUnits = [
            ['seconds', 1],
            ['minutes', 60],
            ['hours', 60],
            ['days', 24],
            ['weeks', 7],
        ];
        // Accumulator - get all our units in terms of the first...
        var multiplier = 1;
        for (var u of timeUnits) {
            u[1] *= multiplier;
            multiplier = u[1];
            timeConversions[u[0]] = u[1];
        }
        return timeUnits;
    }
}

function secondsToTime (s) {
    var units = getTimeUnits().slice();
    var unitsToUse = [];
    var remainder = s;
    while (units.length>0) {
        var biggest = units.pop();
        if ((remainder / biggest[1]) > 1) {
            unitsToUse.push(
                {amount:Math.floor(remainder/biggest[1]),
                 unit:biggest[0]}
            );
            remainder = remainder % biggest[1];
        }
    }
    return unitsToUse;
}

/*
* get time from messy user strings, such as...
* 30:00 -> 30 minutes
* 30 minutes -> 30 minutes
* 1/2 hour -> 30 minutes
* 2 weeks, 3 days -> 2 weeks + 3 days
* etc.
* Time is returned in seconds.
*/

function timeFromString (txt) {
    var parsers = [checkForColonTimeString,checkForTimeWords];
    for (var parse of parsers) {
        var result = parse(txt);
        if (result) {
            return result
        }
    }
}

function checkForTimeWords (txt) {
    getTimeUnits();
    var total = 0;
    for (var unit in timeEquivRegexps) {
        var re = timeEquivRegexps[unit];
        var match = txt.match(re);
        if (match) {
            var num = fracToFloat(match[1]);
            var converter = timeConversions[unit];
            if (!converter) {
                throw 'No converter found for unit '+unit;
            }
            total += converter * num;
        }
    }
    return total;
}

function checkForColonTimeString (txt) {
    var hourMinute = /^\s*[0-9][0-9]?:[0-9][0-9]\s*$/;
    var hourMinuteSecond = /^\s*[0-9][0-9]?:[0-9][0-9]:[0-9][0-9]\s*$/;
    if (txt.match(hourMinute)) {
        var times = txt.split(':').map(Number);
        return times[0] * 60*60 + times[1]*60;
    }
    if (txt.match(hourMinuteSecond)) {
        var times = txt.split(':').map(Number);
        
        return (
            (times[0] * 60*60) + // hours
                (times[1]*60) + // minutes 
                (times[2])); // seconds
    }
}

